#!/usr/bin/env python3
"""
Analyze abilities.json to extract exhaustive field usage statistics.
Generated by: cards/ability_docs_scripts/analyze_abilities.py
"""

import json
from collections import defaultdict
from pathlib import Path


def safe_write(text, file_obj):
    """Safely write text handling unicode characters."""
    try:
        file_obj.write(text)
    except UnicodeEncodeError:
        # Replace problematic characters
        safe_text = text.encode("utf-8", errors="replace").decode("utf-8")
        file_obj.write(safe_text)


def analyze_abilities(file_path):
    with open(file_path, "r", encoding="utf-8") as f:
        data = json.load(f)

    abilities = data.get("unique_abilities", [])

    # Track which keys are used for each action/type
    cost_keys_by_type = defaultdict(set)
    effect_keys_by_action = defaultdict(set)

    all_cost_keys = set()
    all_effect_keys = set()

    # Track examples for each key
    cost_key_examples = defaultdict(list)
    effect_key_examples = defaultdict(list)

    for ab in abilities:
        cost = ab.get("cost")
        effect = ab.get("effect")
        card_refs = ab.get("cards", [])

        if cost:
            c_type = cost.get("type", "unknown")
            for k in cost.keys():
                cost_keys_by_type[c_type].add(k)
                all_cost_keys.add(k)
                cost_key_examples[k].extend(card_refs[:2])  # Add up to 2 examples

        if effect:
            action = effect.get("action", "unknown")
            for k in effect.keys():
                effect_keys_by_action[action].add(k)
                all_effect_keys.add(k)
                effect_key_examples[k].extend(card_refs[:2])  # Add up to 2 examples

    # Create output directory
    output_dir = Path(__file__).parent
    output_dir.mkdir(exist_ok=True)

    # Write all cost keys with examples
    with open(output_dir / "all_cost_keys.txt", "w", encoding="utf-8") as f:
        safe_write("# All Cost Keys\n", f)
        safe_write(
            "# Generated by: cards/ability_docs_scripts/analyze_abilities.py\n\n", f
        )
        safe_write("All Cost Keys:\n", f)
        for key in sorted(list(all_cost_keys)):
            examples = cost_key_examples[key][:2] if cost_key_examples[key] else []
            example_str = f" (e.g., {', '.join(examples)})" if examples else ""
            safe_write(f"  {key}{example_str}\n", f)

    # Write all effect keys with examples
    with open(output_dir / "all_effect_keys.txt", "w", encoding="utf-8") as f:
        safe_write("# All Effect Keys\n", f)
        safe_write(
            "# Generated by: cards/ability_docs_scripts/analyze_abilities.py\n\n", f
        )
        safe_write("All Effect Keys:\n", f)
        for key in sorted(list(all_effect_keys)):
            examples = effect_key_examples[key][:2] if effect_key_examples[key] else []
            example_str = f" (e.g., {', '.join(examples)})" if examples else ""
            safe_write(f"  {key}{example_str}\n", f)

    # Write cost keys by type with examples
    with open(output_dir / "cost_keys_by_type.txt", "w", encoding="utf-8") as f:
        safe_write("# Cost Keys by Type\n", f)
        safe_write(
            "# Generated by: cards/ability_docs_scripts/analyze_abilities.py\n\n", f
        )
        safe_write("Cost Keys by Type:\n", f)
        for c_type in sorted(cost_keys_by_type.keys()):
            safe_write(f"  {c_type}:\n", f)
            for key in sorted(list(cost_keys_by_type[c_type])):
                examples = cost_key_examples[key][:2] if cost_key_examples[key] else []
                example_str = f" (e.g., {', '.join(examples)})" if examples else ""
                safe_write(f"    - {key}{example_str}\n", f)
            safe_write("\n", f)

    # Write effect keys by action with examples
    with open(output_dir / "effect_keys_by_action.txt", "w", encoding="utf-8") as f:
        safe_write("# Effect Keys by Action\n", f)
        safe_write(
            "# Generated by: cards/ability_docs_scripts/analyze_abilities.py\n\n", f
        )
        safe_write("Effect Keys by Action:\n", f)
        for action in sorted(effect_keys_by_action.keys()):
            safe_write(f"  {action}:\n", f)
            for key in sorted(list(effect_keys_by_action[action])):
                examples = (
                    effect_key_examples[key][:2] if effect_key_examples[key] else []
                )
                example_str = f" (e.g., {', '.join(examples)})" if examples else ""
                safe_write(f"    - {key}{example_str}\n", f)
            safe_write("\n", f)

    # Count abilities per action type
    action_ability_counts = defaultdict(int)
    cost_type_ability_counts = defaultdict(int)
    for ab in abilities:
        effect = ab.get("effect") or {}
        action = effect.get("action", "")
        if action:
            action_ability_counts[action] += 1
        cost = ab.get("cost") or {}
        cost_type = cost.get("type", "")
        if cost_type:
            cost_type_ability_counts[cost_type] += 1

    # Also create a comprehensive summary file
    with open(
        output_dir / "abilities_analysis_summary.txt", "w", encoding="utf-8"
    ) as f:
        safe_write("# Abilities Analysis Summary\n", f)
        safe_write(
            "# Generated by: cards/ability_docs_scripts/analyze_abilities.py\n\n", f
        )
        safe_write("ABILITIES ANALYSIS SUMMARY\n", f)
        safe_write("=" * 50 + "\n\n", f)

        safe_write("OVERVIEW\n", f)
        safe_write("-" * 50 + "\n", f)
        safe_write("  Total unique abilities: {}\n".format(len(abilities)), f)
        safe_write("  Total cost types: {}\n".format(len(cost_keys_by_type)), f)
        safe_write("  Total effect actions: {}\n".format(len(effect_keys_by_action)), f)
        safe_write("  Total cost keys: {}\n".format(len(all_cost_keys)), f)
        safe_write("  Total effect keys: {}\n".format(len(all_effect_keys)), f)
        safe_write("\n", f)

        safe_write("ABILITIES PER EFFECT ACTION (sorted by count):\n", f)
        safe_write("-" * 50 + "\n", f)
        for action, count in sorted(action_ability_counts.items(), key=lambda x: -x[1]):
            safe_write("  {:4d}  {}\n".format(count, action), f)
        safe_write("\n", f)

        safe_write("ABILITIES PER COST TYPE (sorted by count):\n", f)
        safe_write("-" * 50 + "\n", f)
        for ct, count in sorted(cost_type_ability_counts.items(), key=lambda x: -x[1]):
            safe_write("  {:4d}  {}\n".format(count, ct), f)
        safe_write("\n", f)

        safe_write("ALL COST KEYS ({} total):\n".format(len(all_cost_keys)), f)
        for key in sorted(list(all_cost_keys)):
            examples = cost_key_examples[key][:2] if cost_key_examples[key] else []
            example_str = (
                " (e.g., {}, {})".format(examples[0], examples[1])
                if len(examples) >= 2
                else " (e.g., {})".format(examples[0])
                if examples
                else ""
            )
            safe_write("  - {}{}\n".format(key, example_str), f)
        safe_write("\n", f)

        safe_write("ALL EFFECT KEYS ({} total):\n".format(len(all_effect_keys)), f)
        for key in sorted(list(all_effect_keys)):
            examples = effect_key_examples[key][:2] if effect_key_examples[key] else []
            example_str = (
                " (e.g., {}, {})".format(examples[0], examples[1])
                if len(examples) >= 2
                else " (e.g., {})".format(examples[0])
                if examples
                else ""
            )
            safe_write("  - {}{}\n".format(key, example_str), f)
        safe_write("\n", f)

        safe_write("COST KEYS BY TYPE:\n", f)
        for c_type in sorted(cost_keys_by_type.keys()):
            safe_write(
                "  {} ({} abilities):\n".format(
                    c_type, cost_type_ability_counts.get(c_type, 0)
                ),
                f,
            )
            for key in sorted(list(cost_keys_by_type[c_type])):
                examples = cost_key_examples[key][:2] if cost_key_examples[key] else []
                example_str = (
                    " (e.g., {}, {})".format(examples[0], examples[1])
                    if len(examples) >= 2
                    else " (e.g., {})".format(examples[0])
                    if examples
                    else ""
                )
                safe_write("    - {}{}\n".format(key, example_str), f)
            safe_write("\n", f)

        safe_write("EFFECT KEYS BY ACTION:\n", f)
        for action in sorted(effect_keys_by_action.keys()):
            safe_write(
                "  {} ({} abilities):\n".format(
                    action, action_ability_counts.get(action, 0)
                ),
                f,
            )
            for key in sorted(list(effect_keys_by_action[action])):
                examples = (
                    effect_key_examples[key][:2] if effect_key_examples[key] else []
                )
                example_str = (
                    " (e.g., {}, {})".format(examples[0], examples[1])
                    if len(examples) >= 2
                    else " (e.g., {})".format(examples[0])
                    if examples
                    else ""
                )
                safe_write("    - {}{}\n".format(key, example_str), f)
            safe_write("\n", f)

        safe_write("ALL EFFECT KEYS ({} total):\n".format(len(all_effect_keys)), f)
        for key in sorted(list(all_effect_keys)):
            examples = effect_key_examples[key][:2] if effect_key_examples[key] else []
            example_str = f" (e.g., {', '.join(examples)})" if examples else ""
            safe_write("  - {}{}\n".format(key, example_str), f)
        safe_write("\n", f)

        safe_write("COST KEYS BY TYPE:\n", f)
        for c_type in sorted(cost_keys_by_type.keys()):
            safe_write("  {}:\n".format(c_type), f)
            for key in sorted(list(cost_keys_by_type[c_type])):
                examples = cost_key_examples[key][:2] if cost_key_examples[key] else []
                example_str = f" (e.g., {', '.join(examples)})" if examples else ""
                safe_write("    - {}{}\n".format(key, example_str), f)
            safe_write("\n", f)

        safe_write("EFFECT KEYS BY ACTION:\n", f)
        for action in sorted(effect_keys_by_action.keys()):
            safe_write("  {}:\n".format(action), f)
            for key in sorted(list(effect_keys_by_action[action])):
                examples = (
                    effect_key_examples[key][:2] if effect_key_examples[key] else []
                )
                example_str = f" (e.g., {', '.join(examples)})" if examples else ""
                safe_write("    - {}{}\n".format(key, example_str), f)
            safe_write("\n", f)


if __name__ == "__main__":
    abilities_file = Path(__file__).parent.parent / "abilities.json"
    analyze_abilities(abilities_file)
